const _fs=document.createElement("style");
_fs.textContent="@font-face { font-family: 'HelveticaNeueLTStd'; font-weight: 700; src: url('data:font/opentype;base64,') format('opentype'); font-display: swap; }   @font-face { font-family: 'HelveticaNeue107'; font-weight: 900; src: url('data:font/otf;base64,') format('opentype'); font-display: swap; } @font-face { font-family: 'GuzmanBoldCaps'; font-weight: 700; src: url('data:font/truetype;base64,') format('truetype'); font-display: swap; } @font-face { font-family: 'HelveticaNeueLTStd'; font-weight: 400; src: url('data:font/opentype;base64,') format('opentype'); font-display: swap; }";
if(!document.head.querySelector('style[data-gyg-fonts]')){_fs.setAttribute("data-gyg-fonts","1");document.head.appendChild(_fs);}
const FC="'HelveticaNeueLTStd','HelveticaNeue-CondensedBold','Helvetica Neue','Arial Narrow',sans-serif";
const FB="'HelveticaNeueLTStd','Helvetica Neue',Helvetica,Arial,sans-serif";
